-- ComplianceTrack control register seed, derived from the official
-- NCA Essential Cybersecurity Controls (ECC-2:2024) publication.
-- 108 main controls across 4 domains and 28 subdomains.
--   scope_tier = 'in_scope'     : implemented and tracked by this prototype
--   scope_tier = 'catalog_only' : shown for framework completeness only

INSERT INTO controls (ecc_reference, domain, subdomain, description,
                      owner_user_id, status, review_date, scope_tier) VALUES
  ('1-1-1', 'Cybersecurity Governance', 'Cybersecurity Strategy',
   'The cybersecurity strategy of the entity shall be identified, documented, and approved, and it shall be supported by the head of the entity or his/her delegate (Hereinafter referred to as the "Authorized Official"). The strategy goals shall be in line with the relevant legislative and regulatory requirements.',
   (SELECT user_id FROM users WHERE username = 'm.otaibi'), 'Implemented', '2026-10-15'::date, 'in_scope'),
  ('1-1-2', 'Cybersecurity Governance', 'Cybersecurity Strategy',
   'The entity shall execute an action plan to apply the cybersecurity strategy.',
   (SELECT user_id FROM users WHERE username = 's.harbi'), 'Partially Implemented', '2026-10-26'::date, 'in_scope'),
  ('1-1-3', 'Cybersecurity Governance', 'Cybersecurity Strategy',
   'The cybersecurity strategy shall be reviewed at planned intervals (or in case of changes to the relevant legislative and regulatory requirements).',
   (SELECT user_id FROM users WHERE username = 'a.rashid'), 'Not Implemented', '2026-11-06'::date, 'in_scope'),
  ('1-2-1', 'Cybersecurity Governance', 'Cybersecurity Management',
   'A department for cybersecurity shall be established within the entity. This department shall be independent from the Information Technology and Communications Department (As per High Order No. 37140, dated 14/08/1438H.). It is recommended that the Cybersecurity Department reports directly to the head of the entity or his/her delegate while ensuring that this does not result in a conflict of interests.',
   (SELECT user_id FROM users WHERE username = 'm.otaibi'), 'Implemented', '2026-11-17'::date, 'in_scope'),
  ('1-2-2', 'Cybersecurity Governance', 'Cybersecurity Management',
   'All cybersecurity positions shall be filled out with full-time and qualified Saudi cybersecurity professionals.',
   (SELECT user_id FROM users WHERE username = 's.harbi'), 'Evidence Missing', '2026-11-28'::date, 'in_scope'),
  ('1-2-3', 'Cybersecurity Governance', 'Cybersecurity Management',
   'A cybersecurity supervisory committee shall be established pursuant to the instruction of the entity''s Authorized Official to ensure compliance with, support for, and monitoring of the implementation of the cybersecurity programs and regulations. The committee''s members, responsibilities, and governance framework shall be identified, documented, and approved. The committee shall include the head of the cybersecurity department as a member. It is recommended that the committee reports directly to the head of the entity or his/her delegate while ensuring that this does not result in a conflict of interests.',
   (SELECT user_id FROM users WHERE username = 'a.rashid'), 'Partially Implemented', '2026-12-09'::date, 'in_scope'),
  ('1-3-1', 'Cybersecurity Governance', 'Cybersecurity Policies and Procedures',
   'The cybersecurity department of the entity shall identify and document cybersecurity policies and procedures, including the cybersecurity controls and requirements, and have them approved by the entity''s Authorized Official, and communicate them to the relevant personnel and parties inside the entity.',
   (SELECT user_id FROM users WHERE username = 'm.otaibi'), 'Implemented', '2026-12-20'::date, 'in_scope'),
  ('1-3-2', 'Cybersecurity Governance', 'Cybersecurity Policies and Procedures',
   'The cybersecurity department shall ensure that the cybersecurity policies and procedures, including the relevant controls and requirements, are implemented at the entity.',
   (SELECT user_id FROM users WHERE username = 's.harbi'), 'Not Applicable', '2026-12-31'::date, 'in_scope'),
  ('1-3-3', 'Cybersecurity Governance', 'Cybersecurity Policies and Procedures',
   'The cybersecurity policies and procedures shall be supported by technical security standards (e.g. technical security standards for firewall, databases, operating systems, etc.).',
   (SELECT user_id FROM users WHERE username = 'a.rashid'), 'Implemented', '2027-01-11'::date, 'in_scope'),
  ('1-3-4', 'Cybersecurity Governance', 'Cybersecurity Policies and Procedures',
   'The cybersecurity policies and procedures shall be reviewed and updated at planned intervals (or in case of changes to the relevant legislative and regulatory requirements and standards). Changes shall be documented and approved.',
   (SELECT user_id FROM users WHERE username = 'm.otaibi'), 'Partially Implemented', '2027-01-22'::date, 'in_scope'),
  ('1-4-1', 'Cybersecurity Governance', 'Cybersecurity Roles and Responsibilities',
   'The Authorized Official shall identify, document, and approve the governance organizational structure, roles, and responsibilities of the entity''s cybersecurity, and assign the persons concerned therewith. The necessary support shall be provided for the implementation thereof while ensuring that this does not result in a conflict of interests.',
   (SELECT user_id FROM users WHERE username = 's.harbi'), 'Not Implemented', '2027-02-02'::date, 'in_scope'),
  ('1-4-2', 'Cybersecurity Governance', 'Cybersecurity Roles and Responsibilities',
   'The cybersecurity roles and responsibilities within the entity shall be reviewed and updated at planned intervals (or in case of changes to the relevant legislative and regulatory requirements).',
   (SELECT user_id FROM users WHERE username = 'a.rashid'), 'Implemented', '2027-02-13'::date, 'in_scope'),
  ('1-5-1', 'Cybersecurity Governance', 'Cybersecurity Risk Management',
   'The cybersecurity department of the entity shall identify, document, and approve the cybersecurity risk management methodology and procedures within the entity, in accordance with considerations of confidentiality, and the integrity and availability of information and technology assets.',
   (SELECT user_id FROM users WHERE username = 'm.otaibi'), 'Evidence Missing', '2027-02-24'::date, 'in_scope'),
  ('1-5-2', 'Cybersecurity Governance', 'Cybersecurity Risk Management',
   'The cybersecurity department shall implement the cybersecurity risk management methodology and procedures within the entity.',
   (SELECT user_id FROM users WHERE username = 's.harbi'), 'Partially Implemented', '2027-03-07'::date, 'in_scope'),
  ('1-5-3', 'Cybersecurity Governance', 'Cybersecurity Risk Management',
   'The cybersecurity risk assessment procedures shall be implemented at least in the following cases: 1.5.3.1 At early stage of technology projects. 1.5.3.2 Before making major changes to technology infrastructure. 1.5.3.3 During planning to obtain third party services. 1.5.3.4 During planning and before the release of new technology services and products.',
   (SELECT user_id FROM users WHERE username = 'a.rashid'), 'Implemented', '2027-03-18'::date, 'in_scope'),
  ('1-5-4', 'Cybersecurity Governance', 'Cybersecurity Risk Management',
   'The cybersecurity risk management methodology and procedures shall be reviewed and updated at planned intervals (or in case of changes to the relevant legislative and regulatory requirements and standards). Changes shall be documented and approved.',
   (SELECT user_id FROM users WHERE username = 'm.otaibi'), 'Not Applicable', '2027-03-29'::date, 'in_scope'),
  ('1-6-1', 'Cybersecurity Governance', 'Cybersecurity in Information and Technology Project Management',
   'Cybersecurity requirements shall be included in the project management methodology and procedures and in the information and technology asset change management within the entity to ensure identifying and managing cybersecurity risks as part of the technology project lifecycle. The cybersecurity requirements shall be a key part of the requirements for technology projects.',
   (SELECT user_id FROM users WHERE username = 's.harbi'), 'Implemented', '2027-04-09'::date, 'in_scope'),
  ('1-6-2', 'Cybersecurity Governance', 'Cybersecurity in Information and Technology Project Management',
   'The cybersecurity requirements for project management and information and technology asset changes within the entity shall include the following as a minimum: 1.6.2.1 Vulnerability assessment and remediation. 1.6.2.2 Reviewing secure configuration and hardening and updates packages before launching projects and changes.',
   (SELECT user_id FROM users WHERE username = 'a.rashid'), 'Partially Implemented', '2026-10-22'::date, 'in_scope'),
  ('1-6-3', 'Cybersecurity Governance', 'Cybersecurity in Information and Technology Project Management',
   'The cybersecurity requirements for software and application development projects within the entity shall include the following as a minimum: 1.6.3.1 Using the secure coding standards. 1.6.3.2 Using trusted and licensed sources for software development tools and libraries. 1.6.3.3 Conducting compliance test for software against the cybersecurity requirements within the entity. 1.6.3.4 Secure integration between applications. 1.6.3.5 Reviewing secure configuration and hardening and updates packages before launching software products',
   (SELECT user_id FROM users WHERE username = 'm.otaibi'), 'Not Implemented', '2026-11-02'::date, 'in_scope'),
  ('1-6-4', 'Cybersecurity Governance', 'Cybersecurity in Information and Technology Project Management',
   'The cybersecurity requirements for project management within the entity shall be periodically reviewed.',
   (SELECT user_id FROM users WHERE username = 's.harbi'), 'Implemented', '2026-11-13'::date, 'in_scope'),
  ('1-7-1', 'Cybersecurity Governance', 'Compliance with Cybersecurity Standards, Laws and Regulations',
   'If there are nationally approved international agreements or commitments that include cybersecurity requirements, the entity shall identify and comply with these requirements.',
   (SELECT user_id FROM users WHERE username = 'a.rashid'), 'Evidence Missing', '2026-11-24'::date, 'in_scope'),
  ('1-8-1', 'Cybersecurity Governance', 'Periodical Cybersecurity Review and Audit',
   'The cybersecurity department of the entity shall periodically review the implementation of cybersecurity controls by the entity.',
   (SELECT user_id FROM users WHERE username = 'm.otaibi'), 'Partially Implemented', '2026-12-05'::date, 'in_scope'),
  ('1-8-2', 'Cybersecurity Governance', 'Periodical Cybersecurity Review and Audit',
   'The implementation of cybersecurity controls by the entity shall be reviewed and audited by parties other than the cybersecurity department at the entity, provided that the audit and review are to be conducted independently while considering the principle of conflict of interest, as per the Generally Accepted Auditing Standards (GAAS) and the relevant legislative and regulatory requirements.',
   (SELECT user_id FROM users WHERE username = 's.harbi'), 'Implemented', '2026-12-16'::date, 'in_scope'),
  ('1-8-3', 'Cybersecurity Governance', 'Periodical Cybersecurity Review and Audit',
   'The results of cybersecurity audits and reviews shall be documented and presented to the cybersecurity supervisory committee and the Authorized Official. Results shall include the audit and review scope, observations, recommendations, corrective actions, and remediation plans.',
   (SELECT user_id FROM users WHERE username = 'a.rashid'), 'Not Applicable', '2026-12-27'::date, 'in_scope'),
  ('1-9-1', 'Cybersecurity Governance', 'Cybersecurity in Human Resources',
   'Cybersecurity requirements for personnel of the entity shall be identified, documented, and approved prior to, during, and upon the end or termination of their employment.',
   (SELECT user_id FROM users WHERE username = 'm.otaibi'), 'Implemented', '2027-01-07'::date, 'in_scope'),
  ('1-9-2', 'Cybersecurity Governance', 'Cybersecurity in Human Resources',
   'Cybersecurity requirements for personnel of the entity shall be implemented.',
   (SELECT user_id FROM users WHERE username = 's.harbi'), 'Partially Implemented', '2027-01-18'::date, 'in_scope'),
  ('1-9-3', 'Cybersecurity Governance', 'Cybersecurity in Human Resources',
   'Cybersecurity requirements prior to the commencement of the employment relationship between personnel and the entity shall include the following as a minimum: 1.9.3.1 Incorporating the personnel''s cybersecurity responsibilities clauses and non- disclosure clauses in their employment contracts with the entity (including during and after employment end/termination with the entity). 1.9.3.2 Conducting screening or vetting for personnel in cybersecurity positions and technical positions with critical and privileged powers.',
   (SELECT user_id FROM users WHERE username = 'a.rashid'), 'Not Implemented', '2027-01-29'::date, 'in_scope'),
  ('1-9-4', 'Cybersecurity Governance', 'Cybersecurity in Human Resources',
   'Cybersecurity requirements for personnel during their employment relationship with the entity shall include the following as a minimum: 1.9.4.1 Cybersecurity awareness (during on-boarding and during employment). 1.9.4.2 Implementation and compliance with cybersecurity requirements, as per the entity''s cybersecurity policies, procedures, and operations.',
   (SELECT user_id FROM users WHERE username = 'm.otaibi'), 'Implemented', '2027-02-09'::date, 'in_scope'),
  ('1-9-5', 'Cybersecurity Governance', 'Cybersecurity in Human Resources',
   'The personnel''s powers shall be reviewed and revoked immediately upon the end/termination of their employment with the entity.',
   (SELECT user_id FROM users WHERE username = 's.harbi'), 'Evidence Missing', '2027-02-20'::date, 'in_scope'),
  ('1-9-6', 'Cybersecurity Governance', 'Cybersecurity in Human Resources',
   'Cybersecurity requirements for personnel of the entity shall be periodically reviewed.',
   (SELECT user_id FROM users WHERE username = 'a.rashid'), 'Partially Implemented', '2027-03-03'::date, 'in_scope'),
  ('1-10-1', 'Cybersecurity Governance', 'Cybersecurity Awareness and Training Program',
   'A cybersecurity awareness program, delivered through multiple channels, shall be periodically developed and approved by the entity to strengthen the awareness about cybersecurity, cyber threats, and risks, and to build a positive cybersecurity awareness culture.',
   (SELECT user_id FROM users WHERE username = 'm.otaibi'), 'Implemented', '2027-03-14'::date, 'in_scope'),
  ('1-10-2', 'Cybersecurity Governance', 'Cybersecurity Awareness and Training Program',
   'The approved cybersecurity awareness program shall be implemented within the entity.',
   (SELECT user_id FROM users WHERE username = 's.harbi'), 'Not Applicable', '2027-03-25'::date, 'in_scope'),
  ('1-10-3', 'Cybersecurity Governance', 'Cybersecurity Awareness and Training Program',
   'The cybersecurity awareness program shall include how to protect the entity against the most important and latest cyber risks and threats, including: 1.10.3.1 Secure handling of email services, especially phishing emails. 1.10.3.2 Secure handling of mobile devices and storage media. 1.10.3.3 Secure Internet browsing. 1.10.3.4 Secure usage of social media.',
   (SELECT user_id FROM users WHERE username = 'a.rashid'), 'Implemented', '2027-04-05'::date, 'in_scope'),
  ('1-10-4', 'Cybersecurity Governance', 'Cybersecurity Awareness and Training Program',
   'Specialized skills and necessary training shall be provided to personnel in positions that are linked directly to cybersecurity within the entity. Such skills and training shall be classified in line with their cybersecurity responsibilities, including: 1.10.4.1 Cybersecurity department personnel. 1.10.4.2 Personnel working on software/application development and those working on information and technology assets of the entity. 1.10.4.3 Executive and supervisory positions.',
   (SELECT user_id FROM users WHERE username = 'm.otaibi'), 'Partially Implemented', '2026-10-18'::date, 'in_scope'),
  ('1-10-5', 'Cybersecurity Governance', 'Cybersecurity Awareness and Training Program',
   'The implementation of cybersecurity awareness program within the entity shall be periodically reviewed.',
   (SELECT user_id FROM users WHERE username = 's.harbi'), 'Not Implemented', '2026-10-29'::date, 'in_scope'),
  ('2-1-1', 'Cybersecurity Defense', 'Asset Management',
   'Cybersecurity requirements for managing information and technology assets of the entity shall be identified, documented, and approved.',
   (SELECT user_id FROM users WHERE username = 'a.rashid'), 'Implemented', '2026-11-09'::date, 'in_scope'),
  ('2-1-2', 'Cybersecurity Defense', 'Asset Management',
   'Cybersecurity requirements for managing information and technology assets of the entity shall be implemented.',
   (SELECT user_id FROM users WHERE username = 'm.otaibi'), 'Evidence Missing', '2026-11-20'::date, 'in_scope'),
  ('2-1-3', 'Cybersecurity Defense', 'Asset Management',
   'The policy of acceptable use of information and technology assets of the entity shall be identified, documented, approved, and communicated.',
   (SELECT user_id FROM users WHERE username = 's.harbi'), 'Partially Implemented', '2026-12-01'::date, 'in_scope'),
  ('2-1-4', 'Cybersecurity Defense', 'Asset Management',
   'The policy of acceptable use of information and technology assets of the entity shall be implemented.',
   (SELECT user_id FROM users WHERE username = 'a.rashid'), 'Implemented', '2026-12-12'::date, 'in_scope'),
  ('2-1-5', 'Cybersecurity Defense', 'Asset Management',
   'Information and technology assets of the entity shall be classified, labeled, and handled as per the relevant legislative and regulatory requirements.',
   (SELECT user_id FROM users WHERE username = 'm.otaibi'), 'Not Applicable', '2026-12-23'::date, 'in_scope'),
  ('2-1-6', 'Cybersecurity Defense', 'Asset Management',
   'Cybersecurity requirements for managing information and technology assets of the entity shall be periodically reviewed.',
   (SELECT user_id FROM users WHERE username = 's.harbi'), 'Implemented', '2027-01-03'::date, 'in_scope'),
  ('2-2-1', 'Cybersecurity Defense', 'Identity and Access Management',
   'Cybersecurity requirements for identity and access management of the entity shall be identified, documented, and approved.',
   (SELECT user_id FROM users WHERE username = 'a.rashid'), 'Partially Implemented', '2027-01-14'::date, 'in_scope'),
  ('2-2-2', 'Cybersecurity Defense', 'Identity and Access Management',
   'Cybersecurity requirements for identity and access management of the entity shall be implemented.',
   (SELECT user_id FROM users WHERE username = 'm.otaibi'), 'Not Implemented', '2027-01-25'::date, 'in_scope'),
  ('2-2-3', 'Cybersecurity Defense', 'Identity and Access Management',
   'Cybersecurity requirements for identity and access management of the entity shall include the following as a minimum: 2.2.3.1 Single-factor authentication based on username and password. 2.2.3.2 Multi-factor authentication, and defining the suitable authentication factors and their numbers as well as the suitable authentication techniques based on the result of impact assessment of authentication failure and bypass for remote access and for privileged accounts. 2.2.3.3 User authorization based on identity and access control principles (Need-to- Know and Need-to-Use principle, Least Privilege principle, and Segregation of Duties principle). 2.2.3.4 Privileged access management. 2.2.3.5 Periodic review of identities and access rights.',
   (SELECT user_id FROM users WHERE username = 's.harbi'), 'Implemented', '2027-02-05'::date, 'in_scope'),
  ('2-2-4', 'Cybersecurity Defense', 'Identity and Access Management',
   'The implementation of cybersecurity requirements for identity and access management of the entity shall be periodically reviewed.',
   (SELECT user_id FROM users WHERE username = 'a.rashid'), 'Evidence Missing', '2027-02-16'::date, 'in_scope'),
  ('2-3-1', 'Cybersecurity Defense', 'Information System and Processing Facilities Protection',
   'Cybersecurity requirements for protection of information system and processing facilities of the entity shall be identified, documented, and approved.',
   NULL, 'Not Yet In Scope', NULL, 'catalog_only'),
  ('2-3-2', 'Cybersecurity Defense', 'Information System and Processing Facilities Protection',
   'Cybersecurity requirements for protection of information systems and processing facilities of the entity shall be implemented.',
   NULL, 'Not Yet In Scope', NULL, 'catalog_only'),
  ('2-3-3', 'Cybersecurity Defense', 'Information System and Processing Facilities Protection',
   'Cybersecurity requirements for protection of information systems and processing facilities of the entity shall include the following as a minimum: 2.3.3.1 Protection from viruses, suspicious programs and activities, and malware on workstations and servers, using modern and advanced protection technologies and mechanisms, and securely managing them. 2.3.3.2 Strict restriction on the use of external storage media and their security. 2.3.3.3 Patch management for systems, applications, and devices. 2.3.3.4 Centralized clock synchronization with an accurate and trusted source, such as sources provided by the Saudi Standards, Metrology and Quality Organization (SASO).',
   NULL, 'Not Yet In Scope', NULL, 'catalog_only'),
  ('2-3-4', 'Cybersecurity Defense', 'Information System and Processing Facilities Protection',
   'The implementation of cybersecurity requirements for protection of the information system and processing facilities of the entity shall be periodically reviewed.',
   NULL, 'Not Yet In Scope', NULL, 'catalog_only'),
  ('2-4-1', 'Cybersecurity Defense', 'Email Protection',
   'Cybersecurity requirements for protection of the email service of the entity shall be identified, documented, and approved.',
   NULL, 'Not Yet In Scope', NULL, 'catalog_only'),
  ('2-4-2', 'Cybersecurity Defense', 'Email Protection',
   'Cybersecurity requirements for protection of email service of the entity shall be implemented.',
   NULL, 'Not Yet In Scope', NULL, 'catalog_only'),
  ('2-4-3', 'Cybersecurity Defense', 'Email Protection',
   'Cybersecurity requirements for protection of the email service of the entity shall include the following as a minimum: 2.4.3.1 Analyzing and filtering email messages (specifically phishing emails and spam emails) using modern and advanced email protection techniques and mechanisms. 2.4.3.2 Multi-factor authentication, and defining the suitable authentication factors and their numbers as well as the suitable authentication techniques based on the result of impact assessment of authentication failure and bypass for remote and webmail access. 2.4.3.3 Email archiving and backup. 2.4.3.4 Secure management and protection against Advanced Persistent Threats (APT), which normally utilize zero-day malware and viruses. 2.4.3.5 Validation of the entity''s email service domains by using Sender Policy Framework (SPF), Domain Keys Identified Mail (DKIM), and Domain Message Authentication Reporting and Conformance (DMARC).',
   NULL, 'Not Yet In Scope', NULL, 'catalog_only'),
  ('2-4-4', 'Cybersecurity Defense', 'Email Protection',
   'The implementation of cybersecurity requirements for email service of the entity shall be periodically reviewed .',
   NULL, 'Not Yet In Scope', NULL, 'catalog_only'),
  ('2-5-1', 'Cybersecurity Defense', 'Networks Security Management',
   'Cybersecurity requirements for the entity''s network security management shall be identified, documented, and approved.',
   NULL, 'Not Yet In Scope', NULL, 'catalog_only'),
  ('2-5-2', 'Cybersecurity Defense', 'Networks Security Management',
   'Cybersecurity requirements for the entity''s network security management shall be implemented.',
   NULL, 'Not Yet In Scope', NULL, 'catalog_only'),
  ('2-5-3', 'Cybersecurity Defense', 'Networks Security Management',
   'Cybersecurity requirements for the entity''s network security management shall include the following as a minimum: 2.5.3.1 Logical or physical isolation and segmentation of network segments in a secure manner which is required to control relevant cybersecurity risks, using firewall and defense-in-depth principle. 2.5.3.2 Isolation of production network from testing and development environment networks. 2.5.3.3 Secure browsing and internet connectivity, including strict restrictions on suspicious websites, file storage/sharing websites, and remote access websites. 2.5.3.4 Wireless network security and protection using secure authentication and encryption techniques and avoiding the connection of wireless networks to the entity''s internal network, except after a comprehensive assessment of subsequent risks, with handling them in a way that protects the technology assets of the entity. 2.5.3.5 Restricting and managing network services, protocols, and ports. 2.5.3.6 Intrusion Prevention Systems (IPS). 2.5.3.7 Security of Domain Name Service (DNS). 2.5.3.8 Secure management and protection of Internet browsing channel against Advanced Persistent Threats (APT), which normally utilize zero-day malware and viruses. 2-5-3-9 Protecting against Distributed Denial of Service (DDoS) attacks to limit risks arising from these attacks.',
   NULL, 'Not Yet In Scope', NULL, 'catalog_only'),
  ('2-5-4', 'Cybersecurity Defense', 'Networks Security Management',
   'The implementation of cybersecurity requirements for the entity''s network security management shall be periodically reviewed.',
   NULL, 'Not Yet In Scope', NULL, 'catalog_only'),
  ('2-6-1', 'Cybersecurity Defense', 'Mobile Devices Security',
   'Cybersecurity requirements for mobile devices and BYOD security when connected to the entity''s network shall be identified, documented, and approved.',
   NULL, 'Not Yet In Scope', NULL, 'catalog_only'),
  ('2-6-2', 'Cybersecurity Defense', 'Mobile Devices Security',
   'Cybersecurity requirements for mobile devices and BYOD security of the entity shall be implemented.',
   NULL, 'Not Yet In Scope', NULL, 'catalog_only'),
  ('2-6-3', 'Cybersecurity Defense', 'Mobile Devices Security',
   'Cybersecurity requirements for mobile devices and BYOD security of the entity shall include the following as a minimum: 2.6.3.1 Separation and encryption of the entity''s data and information stored on mobile devices and BYODs. 2.6.3.2 Controlled and restricted use based on the requirements of the interest of the entity''s business. 2.6.3.3 Deletion of the entity''s data and information stored on mobile devices and BYOD in cases of device loss or after the ending/termination of employment with the entity. 2.6.3.4 Security awareness for users.',
   NULL, 'Not Yet In Scope', NULL, 'catalog_only'),
  ('2-6-4', 'Cybersecurity Defense', 'Mobile Devices Security',
   'The implementation of cybersecurity requirements for mobile devices and BYOD security of the entity shall be periodically reviewed.',
   NULL, 'Not Yet In Scope', NULL, 'catalog_only'),
  ('2-7-1', 'Cybersecurity Defense', 'Data and Information Protection',
   'Cybersecurity requirements for protecting and handling data and information of the entity shall be identified, documented, and approved, as per the relevant legislative and regulatory requirements.',
   (SELECT user_id FROM users WHERE username = 'm.otaibi'), 'Partially Implemented', '2027-02-27'::date, 'in_scope'),
  ('2-7-2', 'Cybersecurity Defense', 'Data and Information Protection',
   'Cybersecurity requirements for protecting data and information of the entity shall be implemented, based on its classification level.',
   (SELECT user_id FROM users WHERE username = 's.harbi'), 'Implemented', '2027-03-10'::date, 'in_scope'),
  ('2-7-3', 'Cybersecurity Defense', 'Data and Information Protection',
   'The implementation of cybersecurity requirements for protecting data and information of the entity shall be periodically reviewed.',
   (SELECT user_id FROM users WHERE username = 'a.rashid'), 'Not Applicable', '2027-03-21'::date, 'in_scope'),
  ('2-8-1', 'Cybersecurity Defense', 'Cryptography',
   'Cybersecurity requirements for cryptography within the entity shall be identified, documented, and approved.',
   (SELECT user_id FROM users WHERE username = 'm.otaibi'), 'Implemented', '2027-04-01'::date, 'in_scope'),
  ('2-8-2', 'Cybersecurity Defense', 'Cryptography',
   'Cybersecurity requirements for cryptography within the entity shall be implemented.',
   (SELECT user_id FROM users WHERE username = 's.harbi'), 'Partially Implemented', '2027-04-12'::date, 'in_scope'),
  ('2-8-3', 'Cybersecurity Defense', 'Cryptography',
   'Cybersecurity requirements for cryptography shall include at least the requirements in the National Cryptographic Standards, published by NCA. The appropriate cryptographic standard level shall be implemented based on the nature and sensitivity of the data, systems, and networks to be protected as well as the entity''s risk assessment, and as per the relevant legislative and regulatory requirements, as follows: 2.8.3.1 Approved cryptographic systems and solutions standards and their technical and regulatory restrictions. 2.8.3.2 Secure management of cryptographic keys during their lifecycles. 2.8.3.3 Encryption of data in-transit and at-rest, as per their classification and the relevant legislative and regulatory requirements.',
   (SELECT user_id FROM users WHERE username = 'a.rashid'), 'Not Implemented', '2026-10-25'::date, 'in_scope'),
  ('2-8-4', 'Cybersecurity Defense', 'Cryptography',
   'The implementation of cybersecurity requirements for cryptography within the entity shall be periodically reviewed.',
   (SELECT user_id FROM users WHERE username = 'm.otaibi'), 'Implemented', '2026-11-05'::date, 'in_scope'),
  ('2-9-1', 'Cybersecurity Defense', 'Backup and Recovery Management',
   'Cybersecurity requirements for backup and recovery management within the entity shall be identified, documented, and approved.',
   NULL, 'Not Yet In Scope', NULL, 'catalog_only'),
  ('2-9-2', 'Cybersecurity Defense', 'Backup and Recovery Management',
   'Cybersecurity requirements for backup and recovery management within the entity shall be implemented.',
   NULL, 'Not Yet In Scope', NULL, 'catalog_only'),
  ('2-9-3', 'Cybersecurity Defense', 'Backup and Recovery Management',
   'Cybersecurity requirements for backup and recovery management shall include the following as a minimum: 2.9.3.1 Scope of backups to cover critical technology and information assets. 2.9.3.2 Ability to perform quick recovery of data and systems after cybersecurity incidents. 2.9.3.3 Periodic testing for the effectiveness of backup recovery.',
   NULL, 'Not Yet In Scope', NULL, 'catalog_only'),
  ('2-9-4', 'Cybersecurity Defense', 'Backup and Recovery Management',
   'The implementation of cybersecurity requirements for backup and recovery management within the entity shall be periodically reviewed.',
   NULL, 'Not Yet In Scope', NULL, 'catalog_only'),
  ('2-10-1', 'Cybersecurity Defense', 'Vulnerabilities Management',
   'Cybersecurity requirements for technical vulnerabilities management within the entity shall be identified, documented, and approved.',
   NULL, 'Not Yet In Scope', NULL, 'catalog_only'),
  ('2-10-2', 'Cybersecurity Defense', 'Vulnerabilities Management',
   'Cybersecurity requirements for technical vulnerabilities management within the entity shall be implemented.',
